-- Xavier Xiong (profileID=24) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Xavier Xiong phrasings

SELECT p.argumentID, p.phrasingID, 24, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 24
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 24 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=24 AND targArgID IN (101,103,107,108,118,130,140,148,161,169,175,217,219,226,313,320,322,323,324,325,326,327,328,329,330,331,333,400,404,407,412,428,459,460,461,462,527,560,561,611,615,616,617,743,746,747,780,781,782,783,839,841,842,844,1001,1002,1177,1179,1181,1385,1386,1440);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 24
SET pe.active = o.acceptance
WHERE pe.profileID = 24;

SELECT 'Done: endorsements for profileID=24' AS status;